//! libsqlite_rs — 1:1 Rust 重构的 SQLite
//!
//! 公开 API 与官方 libsqlite3 完全兼容(同符号名、同 C ABI、同错误码)。
//! 内部使用 PascalCase 类型命名,与 C 源文件结构一一对应。

#![deny(unsafe_op_in_unsafe_fn)]
#![warn(missing_docs)]

mod api;
mod error;
mod handle;
pub mod util;

pub use api::{
    sqlite3_close, sqlite3_errcode, sqlite3_errmsg, sqlite3_libversion,
    sqlite3_libversion_number, sqlite3_malloc, sqlite3_malloc64, sqlite3_free, sqlite3_open,
    sqlite3_open_v2,
};
pub use error::SqliteError;
pub use handle::SqliteDb;
pub use util::alloc::{Malloc, SQLITE_MAX_ALLOCATION_SIZE};

pub const SQLITE_VERSION: &str = env!("SQLITE_VERSION");
